def fault_hours(samples, max_gap_s):
    # Input validation
    if not isinstance(samples, list):
        raise ValueError("samples must be a list")
    if not isinstance(max_gap_s, (int, float)) or max_gap_s <= 0:
        raise ValueError("max_gap_s must be a positive number")

    # Validate each row
    for row in samples:
        if not isinstance(row, (list, tuple)) or len(row) != 3:
            raise ValueError("Each row must be a list or tuple of length 3")
        epoch, fault, active = row
        # Check epoch is numeric but not bool
        if isinstance(epoch, bool):
            raise ValueError("Epoch cannot be a boolean")
        if not isinstance(epoch, (int, float)):
            raise ValueError("Epoch must be a number")
        # Check fault is bool or None
        if fault is not None and not isinstance(fault, bool):
            raise ValueError("fault must be a boolean or None")
        # Check active is bool or None
        if active is not None and not isinstance(active, bool):
            raise ValueError("active must be a boolean or None")

    # Handle empty or single row cases
    if len(samples) <= 1:
        return (0.0, 0.0)

    # Process duplicates: last occurrence wins
    epoch_dict = {}
    for row in samples:
        epoch = row[0]
        epoch_dict[epoch] = row

    # Get unique epochs sorted ascending
    unique_epochs = sorted(epoch_dict.keys())

    if len(unique_epochs) <= 1:
        return (0.0, 0.0)

    fault_seconds = 0.0
    covered_seconds = 0.0

    # Process intervals between consecutive epochs
    for i in range(len(unique_epochs) - 1):
        current_epoch = unique_epochs[i]
        next_epoch = unique_epochs[i + 1]

        # Get current row data
        current_row = epoch_dict[current_epoch]
        current_fault = current_row[1]
        current_active = current_row[2]

        # Calculate interval duration, capped at max_gap_s
        interval_duration = next_epoch - current_epoch
        effective_duration = min(interval_duration, max_gap_s)

        # Skip if effective_duration is non-positive (shouldn't happen with sorted unique epochs)
        if effective_duration <= 0:
            continue

        # Check if current row contributes coverage
        # Coverage requires active is True and fault is an actual bool (not None)
        if current_active is True and current_fault is not None:
            covered_seconds += effective_duration
            if current_fault is True:
                fault_seconds += effective_duration

    # Convert to hours
    fault_hours = fault_seconds / 3600.0
    covered_hours = covered_seconds / 3600.0

    return (fault_hours, covered_hours)
